(26561, 'Acts 7:16', 'Acts', 7, 16, 'د هغوی مړي شکیم ته یووړل شول او په هغې هدیره کې ښخ کړای شول چې ابراهیم د حمور د زامنو څخه په بیه اخیستې وه.', 'د هغوی مری شکیم ته یوورل شول او په هغې هدیره کې شخ کرای شول چې ابراهیم د حمور د زامنو چخه په بیه اخیستې وه.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_7_16.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(26562, 'Acts 7:17', 'Acts', 7, 17, 'کله چې هغه وخت راورسېد چې خدای د ابراهیم سره خپله کړې وعده پوره کړي، نو په دې وخت کې زمونږ د خلکو شمېر په مصر کې ډېر زیات شو.', 'کله چې هغه وخت راورسېد چې خدای د ابراهیم سره خپله کرې وعده پوره کری، نو په دې وخت کې زمونز د خلکو شمېر په مصر کې دېر زیات شو.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_7_17.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26563, 'Acts 7:18', 'Acts', 7, 18, 'بیا په مصر کې یو بل پاچا په تخت کښېناست چې یوسف یې نه پېژانده.', 'بیا په مصر کې یو بل پاچا په تخت کشېناست چې یوسف یې نه پېژانده.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_7_18.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26564, 'Acts 7:19', 'Acts', 7, 19, 'هغه زمونږ د نیکونو سره ټګي وکړه، په هغوی باندې یې ظلم کاوه او هغوی یې دې ته مجبور کړل چې خپل نوي زېږېدلي ماشومان د کورونو څخه دباندې پرېږدي چې مړه شي.', 'هغه زمونز د نیکونو سره تګی وکره، په هغوی باندې یې ظلم کاوه او هغوی یې دې ته مجبور کرل چې خپل نوی زېزېدلی ماشومان د کورونو چخه دباندې پرېزدی چې مره شی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_7_19.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26565, 'Acts 7:20', 'Acts', 7, 20, 'په دې وخت کې موسی وزېږېده. هغه یو ډېر ښکلی ماشوم ؤ او تر درې میاشتو پورې د هغه پالنه د خپل پلار په کور کې کېدله.', 'په دې وخت کې موسی وزېزېده. هغه یو دېر شکلی ماشوم و او تر درې میاشتو پورې د هغه پالنه د خپل پلار په کور کې کېدله.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_7_20.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26566, 'Acts 7:21', 'Acts', 7, 21, 'خو کله چې هغوی مجبور شول چې هغه د کور څخه دباندې پرېږدي، نو د فرعون لور هغه واخیست او د خپل زوی په شان یې د هغه روزنه کوله.', 'خو کله چې هغوی مجبور شول چې هغه د کور چخه دباندې پرېزدی، نو د فرعون لور هغه واخیست او د خپل زوی په شان یې د هغه روزنه کوله.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_7_21.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26567, 'Acts 7:22', 'Acts', 7, 22, 'موسی د مصریانو د ټول حکمت او پوهې تعلیم حاصل کړ. هغه په خبرو او کارونو کې غښتلی شو.', 'موسی د مصریانو د تول حکمت او پوهې تعلیم حاصل کر. هغه په خبرو او کارونو کې غشتلی شو.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_7_22.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26568, 'Acts 7:23', 'Acts', 7, 23, 'کله چې موسی څلوېښت کلن شو، نو په زړه کې یې دا وګرځېدل چې د خپلو اسراییلي ورونو د لیدلو دپاره لاړ شي.', 'کله چې موسی چلوېشت کلن شو، نو په زره کې یې دا وګرجېدل چې د خپلو اسراییلی ورونو د لیدلو دپاره لار شی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_7_23.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26569, 'Acts 7:24', 'Acts', 7, 24, 'کله چې هغه ولیدل چې یو مصري د یو اسراییلي سره بد چلند کاوه، نو هغه ورغی چې د هغه اسراییلي څخه دفاع وکړي او د مصري څخه یې د هغه بدل واخیست او هغه یې وواژه.', 'کله چې هغه ولیدل چې یو مصری د یو اسراییلی سره بد چلند کاوه، نو هغه ورغی چې د هغه اسراییلی چخه دفاع وکری او د مصری چخه یې د هغه بدل واخیست او هغه یې وواژه.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_7_24.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(26570, 'Acts 7:25', 'Acts', 7, 25, 'موسی فکر کاوه چې د هغه خپل قوم به په دې پوه شي چې د ده په وسیله به خدای هغوی ته خلاصون ورکوي، خو هغوی پوه نه شول.', 'موسی فکر کاوه چې د هغه خپل قوم به په دې پوه شی چې د ده په وسیله به خدای هغوی ته خلاصون ورکوی، خو هغوی پوه نه شول.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_7_25.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26571, 'Acts 7:26', 'Acts', 7, 26, 'بله ورځ موسی ولیدل چې دوه اسراییلیانو په خپلو کې سره جګړه کوله او هغه هڅه کوله چې د هغوی ترمنځ روغه جوړه وکړي، نو موسی هغوی ته وویل: ‹ای خلکو! تاسو خو سره ورونه یئ، نو ولې یو د بله سره جګړه کوئ؟›', 'بله ورج موسی ولیدل چې دوه اسراییلیانو په خپلو کې سره جګره کوله او هغه هچه کوله چې د هغوی ترمنج روغه جوره وکری، نو موسی هغوی ته وویل: ‹ای خلکو! تاسو خو سره ورونه یی، نو ولې یو د بله سره جګره کوی؟›', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_7_26.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(26572, 'Acts 7:27', 'Acts', 7, 27, 'خو هغه ملامته سړي موسی ټېل واهه او ورته ویې ویل: ‹ته چا په مونږ باندې حاکم او قاضي ټاکلی یې؟', 'خو هغه ملامته سری موسی تېل واهه او ورته ویې ویل: ‹ته چا په مونز باندې حاکم او قاضی تاکلی یې؟', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_7_27.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(26573, 'Acts 7:28', 'Acts', 7, 28, 'ایا ته غواړې چې د پروني مصري په شان ما هم مړ کړې؟›', 'ایا ته غوارې چې د پرونی مصری په شان ما هم مر کرې؟›', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_7_28.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26574, 'Acts 7:29', 'Acts', 7, 29, 'کله چې موسی دا خبره واورېدله، نو هغه د مصر څخه وتښتېد او مدیان ته لاړ او هلته د مسافر په شان اوسېده. هلته د هغه دوه زامن پیدا شول.', 'کله چې موسی دا خبره واورېدله، نو هغه د مصر چخه وتشتېد او مدیان ته لار او هلته د مسافر په شان اوسېده. هلته د هغه دوه زامن پیدا شول.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_7_29.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(26575, 'Acts 7:30', 'Acts', 7, 30, 'څلوېښت کاله وروسته د سینا غره ته نژدې په یوه دښته کې د یو سوځېدونکي بوټي د اور په لمبو کې یوه فرښته موسی ته ورښکاره شوه.', 'چلوېشت کاله وروسته د سینا غره ته نژدې په یوه دشته کې د یو سوجېدونکی بوتی د اور په لمبو کې یوه فرشته موسی ته ورشکاره شوه.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_7_30.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26576, 'Acts 7:31', 'Acts', 7, 31, 'کله چې موسی هغه ولیدله، نو حیران شو. څنګه چې نژدې ورغی چې هغه ښه وویني، نو د څښتن اواز یې واورېد:', 'کله چې موسی هغه ولیدله، نو حیران شو. چنګه چې نژدې ورغی چې هغه شه ووینی، نو د چشتن اواز یې واورېد:', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_7_31.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(26577, 'Acts 7:32', 'Acts', 7, 32, '‹زه ستا د نیکونو خدای یم، د ابراهیم، اسحاق او یعقوب خدای یم.› موسی له وېرې رپېده او جرات یې نه شو کولای چې ورته وګوري.', '‹زه ستا د نیکونو خدای یم، د ابراهیم، اسحاق او یعقوب خدای یم.› موسی له وېرې رپېده او جرات یې نه شو کولای چې ورته وګوری.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_7_32.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26578, 'Acts 7:33', 'Acts', 7, 33, 'څښتن هغه ته وویل: ‹خپلې څپلۍ وباسه، ځکه په کومه ځمکه باندې چې ته ولاړ یې هغه سپېڅلې ده.', 'چشتن هغه ته وویل: ‹خپلې چپلی وباسه، جکه په کومه جمکه باندې چې ته ولار یې هغه سپېچلې ده.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_7_33.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(26579, 'Acts 7:34', 'Acts', 7, 34, 'ما لیدلي دي چې زما په قوم باندې په مصر کې ظلم کیږي. ما د هغوی فریادونه اورېدلي او زه د هغوی د خلاصون دپاره راښکته شوی یم. اوس راشه، زه تا بېرته مصر ته لېږم.›', 'ما لیدلی دی چې زما په قوم باندې په مصر کې ظلم کیزی. ما د هغوی فریادونه اورېدلی او زه د هغوی د خلاصون دپاره راشکته شوی یم. اوس راشه، زه تا بېرته مصر ته لېزم.›', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_7_34.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(26580, 'Acts 7:35', 'Acts', 7, 35, 'نو دا هماغه موسی دی چې د اسراییلو خلکو رد کړی ؤ او ورته ویلي یې وو: ‹ته چا په مونږ باندې حاکم او قاضي ټاکلی یې؟› خدای همدا موسی د هغې فرښتې په وسیله چې هغه ته د سوځېدونکي بوټي د اور په لمبو کې ښکاره شوه، ولېږه ترڅو د اسراییلو د خلکو حاکم او خلاصوونکی وي.', 'نو دا هماغه موسی دی چې د اسراییلو خلکو رد کری و او ورته ویلی یې وو: ‹ته چا په مونز باندې حاکم او قاضی تاکلی یې؟› خدای همدا موسی د هغې فرشتې په وسیله چې هغه ته د سوجېدونکی بوتی د اور په لمبو کې شکاره شوه، ولېزه ترچو د اسراییلو د خلکو حاکم او خلاصوونکی وی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_7_35.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(26581, 'Acts 7:36', 'Acts', 7, 36, 'دا موسی ؤ چې هغوی یې د مصر څخه راوویستل او په مصر او سره بحیره کې او څلوېښت کاله یې په دښته کې حیرانوونکي کارونه وکړل او معجزې یې وښودلې.', 'دا موسی و چې هغوی یې د مصر چخه راوویستل او په مصر او سره بحیره کې او چلوېشت کاله یې په دشته کې حیرانوونکی کارونه وکرل او معجزې یې وشودلې.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_7_36.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
